#!/usr/bin/env python3
"""Writes FEATURE_SCHEMA.md from src/cssml/feature_schema.py and the snapshot's legacy model definitions (no data read)."""
import os, sys
ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__))); sys.path.insert(0, ROOT)
from uengine import feature_schema as fs, provenance as pv

cc, tr, uc = pv.load_legacy("css_confidence"), pv.load_legacy("train_ranker"), pv.load_legacy("uscore.common", "unified_score")
CONF = set(cc.FEATURES) | {"struct_cls", "struct_s2_mm", "struct_s3_mm", "volume_mm3"}
RANK = set(tr.FEATURES)
used_by = lambda c: ", ".join([k for k, v in fs.MATH_USE.items() if c in v] + [r for r, v in fs.RULE_USE.items() if c in v] +
                              [g for g, v in fs.GATE_USE.items() if c in v] + (["E30 (learned)"] if c == "confidence_pct" else []) +
                              (["confidence model"] if c in CONF else []) + (["ranker"] if c in RANK else []))
counts = {r: len(fs.columns_by_role(r)) for r in fs.ROLES}
L = ["# FEATURE_SCHEMA.md - exact feature definitions and exclusions", "",
     "Generated by `tools/make_feature_schema_md.py` from `unified_engine/uengine/feature_schema.py`; verified against the detector source by",
     "`unified_engine/tests/test_schema.py` (every one of the 157 columns of `detect_css.py` `cols + V50_COLS` is classified exactly once; the columns",
     "each exclusion rule *decides* on are parsed from the verbatim `exclusion_v4` source and must equal `RULE_USE`).", "",
     "## Role counts (157 detector columns)", "", "| role | n | meaning |", "|---|---|---|"]
MEAN = dict(identifier="row / location ids - never predictors", label="reader decision - never a predictor", math_output="MATH outputs (score_v3/v4, evidence)",
            rule_flag="decisions of fixed rules (tiers, zone flags, classes, mimic score)", model_output="LEARNED outputs (v5.10 confidence) - PAST EXPERIENCE",
            quality="data quality / missing-input indicators - quality channel", provenance="versions, configuration, text", categorical="anatomical categories",
            deprecated="known invalid measures", measured="genuinely measured properties - CHARACTERISTICS")
L += [f"| {r} | {counts[r]} | {MEAN[r]} |" for r in fs.ROLES]
L += ["", f"**Measured characteristics: {counts['measured']}.** The brief expected 'approximately 60'. The earlier audit document that stated",
      "that number is not on this Mac, so its counting rule cannot be checked. If redundant variants are collapsed to one per family, see the",
      "'unsuitable for the initial model' column - 99 measured columns, of which " +
      f"{sum(1 for c in fs.measured() if c not in fs.UNSUITABLE_INITIAL)} are not marked redundant / input-dependent / zone-truncated.", "",
      "## Prespecified initial model inputs (10 columns, declared before any evaluation)", "", "| column | source | unit | overlap with MATH (same column already used) |", "|---|---|---|---|"]
for c in fs.INITIAL_COLUMNS:
    src = fs.TRANSFORMS[c][0] if c in fs.TRANSFORMS else fs.INITIAL_INDICATORS.get(c, c)
    tf = " (log, clipped at 1 mm3)" if c in fs.TRANSFORMS else (" (1 = not measurable by design)" if c in fs.INITIAL_INDICATORS else "")
    L.append(f"| `{c}` | `{src}`{tf} | {fs.SCHEMA[src].unit} | {', '.join(fs.overlap_matrix([c]).get(c, []) if c not in fs.INITIAL_INDICATORS else []) or '-'} |")
L += ["", "Rationale: one measure per evidence family of the cSS definition (signal, definition, surface position, cortical contact, two banks,",
      "Hessian tube-vs-sheet, coordinate shape, size, vessel continuation) plus the structural missingness of the tram-track measure. Location",
      "zone shares are excluded from the initial model because hard rules (E1-E27) truncate the population on them and they describe position,",
      "not the lesion. Selection was NOT data-driven.", "",
      "## Every column", "", "| column | role | family | unit | valid range | missing means | consumed by | unsuitable for the initial model because |", "|---|---|---|---|---|---|---|---|"]
fr = lambda c: "-" if c.lo == float("-inf") and c.hi == float("inf") else f"[{'' if c.lo == float('-inf') else c.lo}, {'' if c.hi == float('inf') else c.hi}]"
for c in pv.detector_columns():
    s = fs.SCHEMA[c]
    L.append(f"| `{c}` | {s.role} | {s.family} | {s.unit} | {fr(s)} | {s.missing if s.role == 'measured' else '-'} | {used_by(c) or '-'} | "
             f"{fs.UNSUITABLE_INITIAL.get(c, '') or ('(selected)' if c in fs.INITIAL_FEATURES or c == 'volume_mm3' else ('not a characteristic' if s.role != 'measured' else ''))} |")
L += ["", "## Legacy model inputs (verbatim from the snapshot)", "",
      f"- **v5.10 confidence model** (`css_confidence.FEATURES`, {len(cc.FEATURES)} inputs): " + ", ".join(f"`{f}`" for f in cc.FEATURES) + ".",
      "  Non-measured inputs: `cmb_like` (rule flag) and `is_ball` / `is_tube` / `is_ribbon` (indicators of the rule-derived `struct_cls`).",
      "  Missing values: training median (no missingness indicator) - a structurally unmeasurable `struct_*` or `tram_frac` is treated as an average object.",
      f"- **v5.2 ranker** (`train_ranker.FEATURES`, {len(tr.FEATURES)} inputs incl. 11 pial-surface `surf_*` from a separate file and 4 missing-input",
      "  indicators): includes `mimic_score`, a RULE-DERIVED score (`mimic_rules.py`), as a feature - flagged. Never trained (no `labels/consensus.csv`).",
      f"- **unified score** (`uscore.common.PREDICTORS`): {', '.join(uc.PREDICTORS)} - computed from the images by `uscore/features.py`, not from the",
      "  detector table; unreliable values contribute 0 (training-mean imputation after standardisation). Predeclared fallback drops x4 then x5.", "",
      "## Excluded from every model, with reasons", "",
      "- identifiers, the reader decision, provenance text and versions: carry no lesion property; ids are rank / position artefacts;",
      "- MATH outputs (`score*`, `css_evidence`, `vein_evidence`) and rule flags: they are the MATH component; as predictors they would count MATH twice;",
      "- `confidence_pct` / `confidence_why` / `conf_guard` and any `score_model`: outputs of learned models fitted on the same reads - circular;",
      "- deprecated `vein_tree_mm`, `mirror_dark_frac`, `branch_per10mm`: saturate or carry no information (CLAUDE.md v4.x findings);",
      "- quality columns enter the fusion QUALITY channel (gating), never the evidence."]
with open(os.path.join(os.path.dirname(ROOT), "docs", "unified_engine", "FEATURE_SCHEMA.md"), "w") as fh: fh.write("\n".join(L) + "\n")
print(f"FEATURE_SCHEMA.md: {len(L)} lines")
